draw:
var wRiver = 150;           // metres across
var vCur = p.current;
var vBoat = p.boat;
var head = p.heading * Math.PI / 180;   // measured from straight-across, positive = upstream

// boat velocity relative to ground: x downstream, y across
var vx = vCur - vBoat * Math.sin(head);
var vy = vBoat * Math.cos(head);

var tCross = vy > 0.001 ? wRiver / vy : 0;
var drift = vx * tCross;

var pad = 34;
var xSpanRaw = Math.max(Math.abs(drift) * 1.25, 60);
var sx = (W - 2 * pad) / (2 * xSpanRaw);
var sy = (H - 2 * pad) / wRiver;
var ox = W / 2, oyB = H - pad;
var X = function (x) { return ox + x * sx; };
var Y = function (y) { return oyB - y * sy; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// banks
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(0, Y(wRiver)); ctx.lineTo(W, Y(wRiver)); ctx.stroke();

// current arrows
ctx.strokeStyle = C.faint; ctx.lineWidth = 1.5;
for (var k = 1; k <= 5; k++) {
  var yy = Y(wRiver * k / 6);
  ctx.beginPath(); ctx.moveTo(W * 0.08, yy); ctx.lineTo(W * 0.08 + 26, yy); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.08 + 26, yy); ctx.lineTo(W * 0.08 + 20, yy - 4);
  ctx.moveTo(W * 0.08 + 26, yy); ctx.lineTo(W * 0.08 + 20, yy + 4);
  ctx.stroke();
}

// straight-across reference
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(wRiver)); ctx.stroke();
ctx.setLineDash([]);

if (tCross > 0) {
  // whole path
  ctx.strokeStyle = C.rule; ctx.lineWidth = 1; ctx.setLineDash([4, 5]);
  ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(drift), Y(wRiver)); ctx.stroke();
  ctx.setLineDash([]);

  var now = (t % (tCross + 1.2));
  var cur = Math.min(now, tCross);
  ctx.strokeStyle = C.accent; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(vx * cur), Y(vy * cur)); ctx.stroke();

  var px = X(vx * cur), py = Y(vy * cur);
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();

  // heading arrow (velocity relative to water)
  ctx.strokeStyle = C.figure; ctx.lineWidth = 1.6;
  var hx = px - vBoat * Math.sin(head) * 9, hy = py - vBoat * Math.cos(head) * 9;
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(hx, hy); ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.fillText("heading", hx + 6, hy);

  ctx.fillStyle = C.ink;
  ctx.fillText("landing", X(drift) + 6, Y(wRiver) + 16);
} else {
  ctx.fillStyle = C.ink;
  ctx.fillText("heading too far upstream: she never reaches the far bank", W * 0.12, H / 2);
}

ctx.fillStyle = C.ink;
ctx.fillText("far bank", 8, Y(wRiver) - 8);
ctx.fillText("start", X(0) + 8, Y(0) - 8);
ctx.fillStyle = C.figure;
ctx.fillText("current " + vCur.toFixed(1) + " m/s", W * 0.08, Y(wRiver * 0.5) - 12);

out.note = tCross > 0
  ? "crossing takes " + tCross.toFixed(1) + " s,  downstream drift " + drift.toFixed(1) + " m   (drift = (" + vCur.toFixed(1) + " - " + (vBoat * Math.sin(head)).toFixed(2) + ") x " + tCross.toFixed(1) + ")"
  : "across-stream speed is zero: she never lands";
